export class ManualMonotonicClock {
    #nowMs = 0;
    #waiters = new Set();
    get pendingWaitCount() {
        return this.#waiters.size;
    }
    nowMs() {
        return this.#nowMs;
    }
    waitUntil(deadlineMs, signal) {
        if (signal?.aborted)
            return Promise.resolve("aborted");
        if (deadlineMs <= this.#nowMs)
            return Promise.resolve("deadline");
        return new Promise((resolve) => {
            const waiter = {
                deadlineMs,
                finish: (value) => {
                    this.#waiters.delete(waiter);
                    signal?.removeEventListener("abort", onAbort);
                    resolve(value);
                },
            };
            const onAbort = () => waiter.finish("aborted");
            signal?.addEventListener("abort", onAbort, { once: true });
            this.#waiters.add(waiter);
            if (signal?.aborted)
                waiter.finish("aborted");
        });
    }
    advanceBy(durationMs) {
        if (durationMs < 0) {
            throw new RangeError("Clock duration must be non-negative");
        }
        this.#nowMs += durationMs;
        for (const waiter of [...this.#waiters]) {
            if (waiter.deadlineMs <= this.#nowMs)
                waiter.finish("deadline");
        }
    }
}
export function createDeferred() {
    let settled = false;
    let resolvePromise;
    let rejectPromise;
    const promise = new Promise((resolve, reject) => {
        resolvePromise = resolve;
        rejectPromise = reject;
    });
    return {
        promise,
        get settled() {
            return settled;
        },
        resolve(value) {
            if (settled)
                return;
            settled = true;
            resolvePromise(value);
        },
        reject(error) {
            if (settled)
                return;
            settled = true;
            rejectPromise(error);
        },
    };
}
export function createScriptedStreamProvider(values, options = {}) {
    const queue = values.map((value) => ({
        done: false,
        value,
    }));
    const autoComplete = options.autoComplete ?? true;
    let openCount = 0;
    let nextCount = 0;
    let returnCount = 0;
    let closed = false;
    let returned = false;
    let pending = null;
    const settlePending = (result) => {
        if (pending === null)
            queue.push(result);
        else {
            const current = pending;
            pending = null;
            current.resolve(result);
        }
    };
    return {
        get openCount() {
            return openCount;
        },
        get nextCount() {
            return nextCount;
        },
        get returnCount() {
            return returnCount;
        },
        open(signal) {
            if (openCount > 0)
                throw new Error("Scripted provider supports one open");
            openCount++;
            const close = () => {
                if (closed)
                    return;
                closed = true;
                signal.removeEventListener("abort", onAbort);
            };
            const closeAndSettle = () => {
                close();
                settlePending({ done: true, value: undefined });
            };
            const onAbort = () => closeAndSettle();
            signal.addEventListener("abort", onAbort, { once: true });
            return {
                [Symbol.asyncIterator]() {
                    return {
                        next() {
                            nextCount++;
                            if (closed || signal.aborted) {
                                close();
                                return Promise.resolve({ done: true, value: undefined });
                            }
                            const queued = queue.shift();
                            if (queued) {
                                if (queued.done)
                                    close();
                                return Promise.resolve(queued);
                            }
                            if (autoComplete) {
                                close();
                                return Promise.resolve({ done: true, value: undefined });
                            }
                            if (pending !== null) {
                                return Promise.reject(new Error("Only one scripted provider read may be pending"));
                            }
                            pending = createDeferred();
                            return pending.promise;
                        },
                        return() {
                            if (!returned) {
                                returned = true;
                                returnCount++;
                                if (!closed)
                                    closeAndSettle();
                                if (options.returnError !== undefined) {
                                    return Promise.reject(options.returnError);
                                }
                            }
                            return Promise.resolve({ done: true, value: undefined });
                        },
                    };
                },
            };
        },
        decode(part, _snapshot) {
            return [part];
        },
        classifyError() {
            return {
                code: "PROVIDER_STREAM_ERROR",
                publicMessage: "Provider stream failed",
                retryable: true,
                terminal: false,
            };
        },
        resolveNext(result) {
            settlePending(result);
        },
        rejectNext(error) {
            if (pending === null) {
                throw new Error("No scripted provider read is pending");
            }
            const current = pending;
            pending = null;
            current.reject(error);
        },
    };
}
export function createControllableSignalProvider() {
    return createScriptedStreamProvider([], {
        autoComplete: false,
    });
}
